const legacy:Record<number,string[]>={1:['legacy-2018-password-basic','legacy-2018-password-salted'],2:['legacy-2018-gate-composition','legacy-2018-half-adder'],3:['legacy-2018-members-tables','legacy-2018-members-sql-scaffold'],4:['legacy-2018-cloud-topology']};
