const decode=(text:string)=>text.replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&quot;','"').replaceAll('&#x27;',"'").replaceAll('&#39;',"'").replaceAll('&#xA0;','\u00a0'),plain=(html:string)=>decode(html.replace(/<[^>]*>/g,''));
const bankLabels=[...'アイウエオカキク'];
